import pytest

def test_dividir_por_cero_lanza_zero_division():
    with pytest.raises(ZeroDivisionError):
        dividir(10, 0)

def test_dividir_con_texto_lanza_value_error():
    with pytest.raises(ValueError, match='numericos'):
        dividir('a', 2)

def test_dividir_normal_retorna_cociente():
