import pytest

@pytest.mark.parametrize('edad', [
    pytest.param(0, id='cero'),
    pytest.param(25, id='adulto_joven'),
    pytest.param(150, id='limite_superior'),
])
def test_validar_edad_casos_validos_retornan_true(edad):
    assert validar_edad(edad) is True

def test_validar_edad_negativa_lanza_value_error():
    with pytest.raises(ValueError):
        validar_edad(-1)

def test_validar_edad_mayor_a_150_lanza_value_error():
    with pytest.raises(ValueError):
        validar_edad(151)

